function AlertDetailPage() {
  const { id } = useParams();
  const alert = useAlerts().find((a) => a.id === id);
  if (!alert) return <p>No such alert.</p>;
  return (
    <article>
      <h1>{alert.title}</h1>
      <SeverityBadge severity={alert.severity} />
    </article>
  );
}

function FormPage({ title, onSubmit, submitLabel, children, aside }: FormPageProps) {
  const submit = (e: FormEvent) => { e.preventDefault(); onSubmit(); };
  return (
    <main className="flex flex-col gap-4">
      <h1 className="text-2xl font-bold">{title}</h1>
      <div className="grid gap-6 md:grid-cols-[2fr_1fr]">
        <form noValidate onSubmit={submit} className="flex flex-col gap-4" aria-label={title}>
          {children}
          <Button type="submit" label={submitLabel} />
        </form>
        {aside ? <aside className="flex flex-col gap-3">{aside}</aside> : null}
      </div>
    </main>
  );
}

function Row({ name, state }: { name: string; state: string }) {
  return (
    <li>
      {name} <Pill text={state} />
    </li>
  );
}

function Badge({ label }: { label: string }) {
  return <span className="badge">{label}</span>;
}

async function registerUser(username: string, email: string, password: string) {
  const response = await fetch('/api/signup', {
    method: 'POST',
    body: JSON.stringify({ username, email, password }),
  });
  if (!response.ok) throw new Error('Signup failed');
  return response.json();
}

async function validatedSubmit<V, O, R>(state: SubmitState<V, O, R>, submit: (data: O) => Promise<R>, values?: V): Promise<SubmitState<V, O, R>> {
  const checked = machine.send(state, { type: 'SUBMIT', values }) as SubmitState<V, O, R>;
  if (checked.status !== 'submitting') {
    return checked;
  }
  try {
    const result = await submit(checked.data as O);
    return machine.send(checked, { type: 'RESOLVE', result }) as SubmitState<V, O, R>;
  } catch (error) {
    return machine.send(checked, { type: 'REJECT', error }) as SubmitState<V, O, R>;
  }
}

function isCurrent(state: AsyncState<unknown>, request: number | undefined): boolean {
  if (!state.fetching) {
    return false;
  }
  if (request === undefined) {
    return true;
  }
  return request === state.request;
}

function at<D>(state: FlowState<D>, index: number, data: D, blocked: string | null): FlowState<D> {
  return { ...state, status: positionOf(index, state.steps.length), index, data, visited: Math.max(state.visited, index), blocked };
}

function canUndo(state: HistoryState<unknown>): boolean {
  return state.past.length > 0;
}
